function buildOnline(rnd,item,type){
  var m={n:item.n}, f=item.f, k;
  for(k in f) m[k]=f[k];
  var pts=type.points.map(function(p){return tx(p,m);});
  var off=ri(rnd,0,pts.length-1), kp=[], i;
  for(i=0;i<4;i++) kp.push(pts[(off+i)%pts.length]);
  var facts={};
  type.fact_keys.forEach(function(fk){facts[fk]=m[fk]==null?'':String(m[fk]);});
  return {
    title:item.n+' — '+type.label,
    subject:item.n,
    category:item.c,
    record_type:type.key,
    source:'online',
    source_ref:item.r,
    creation_mode:'ONLINE-CURATED',
    summary:tx(type.summary,m),
    facts:facts,
    key_points:kp,
    guidance:tx(type.guidance,m)
  };
}

function buildSig(rnd,cat){
  var types=CFG.sig_types.filter(function(t){return t.c===cat;});
  if(!types.length) types=CFG.sig_types;
  var type=pick(types,rnd), m={}, i;
  for(i=0;i<type.slots.length;i++){var s=type.slots[i];m[s]=pick(CFG.banks[s],rnd);}
  var pts=type.points.map(function(p){return tx(p,m);});
  var off=ri(rnd,0,pts.length-1), kp=[];
  for(i=0;i<4;i++) kp.push(pts[(off+i)%pts.length]);
  var facts={};
  for(i=0;i<type.fact_keys.length;i++){var fk=type.fact_keys[i];facts[fk]=m[type.fact_map[fk]]==null?'':String(m[type.fact_map[fk]]);}
  return {
    title:tx(type.title_tpl,m),
    subject:tx(type.subject_tpl,m),
    category:cat,
    record_type:type.key,
    source:'signature',
    source_ref:'JAH Signature Generator v1.0',
    creation_mode:'SIGNATURE-GENERATED',
    summary:tx(type.summary,m),
    facts:facts,
    key_points:kp,
    guidance:tx(type.guidance,m)
  };
}

